#nullable enable
using Microsoft.AspNetCore.Mvc;
using Wolverine.Http;
// [WriteAggregate] lives in Wolverine.MARTEN, not Wolverine.Http.Marten — it is the same attribute the
// message handler next door uses, which is exactly the docs claim that [Aggregate] is now a subclass of it.
// No doc page states the namespace; reflection does.
using Wolverine.Http.Marten;
using Wolverine.Marten;
using Drafting.Contracts;

namespace Drafting.Slices.Drafting;

/// <summary>
/// STATE CHANGE, WITH WOLVERINE.HTTP. One method, and everything around it is middleware:
///
///   <c>[WriteAggregate]</c>  fetches the stream, folds it live, and hands the decider the state. It also
///                            takes the stream's version, so the append is optimistically concurrent.
///   <c>[EmptyResponse]</c>   makes the returned event get APPENDED rather than serialised as a body.
///   the validator            runs before this is reached, so SubjectRequired never gets here.
///
/// What is left is the decision, which is the only part a model can never generate.
///
/// THE IDENTITY IS NAMED EXPLICITLY, and finding out why cost two failed runs.
///
/// Both of Wolverine's conventions key off the AGGREGATE TYPE NAME. <c>[Aggregate]</c> looks for a route
/// argument called <c>&lt;AggregateType&gt;Id</c>; plain <c>[WriteAggregate]</c> looks for a command member of
/// the same shape. The aggregate here is <c>ReviseSubjectState</c>, so both hunt for
/// <c>reviseSubjectStateId</c> and neither finds it:
///
///     InvalidOperationException: Unable to determine an aggregate id for the parameter 'draft'
///
/// That is not a quirk of this example. The kit names folds per SLICE on purpose — aggregates are per slice,
/// not per stream — and that naming defeats both conventions outright. The alternatives are an ugly route
/// (<c>/emails/{reviseSubjectStateId}/subject</c>) or naming the fold after the stream and losing the
/// per-slice property. Naming the identity explicitly costs nothing, survives a rename, and keeps both
/// implementations symmetric — the URL still carries <c>{emailId}</c> for the caller's sake.
///
/// It works at all only because the swimlane is keyed by a SINGLE field: <c>[WriteAggregate]</c> reads one
/// value, so a composite key has nothing for it to read. That is the mechanical form of "the aggregate
/// handler workflow does not fit a composite stream key", and why the generator now derives StreamIdentity
/// from the model and stops prefixing single-field keys — a key of <c>email:{guid}</c> could never equal an
/// <c>emailId</c>.
///
/// <c>Required = false</c> IS A DELIBERATE CHOICE, not a default. Left required, a missing stream produces a
/// framework 404 whose body carries no rule name — and this kit's contract is that the rule name is the
/// machine-readable part, because a GWT says <c>then="error: NotDrafted"</c>. So the decider takes the null and
/// answers for itself. The cost is that "the stream must exist" stops being enforced by the framework and
/// becomes a line of code somebody can delete.
/// </summary>
public static class ReviseSubjectEndpoint
{
    public const string Route = "/emails/{emailId}/subject";

    [WolverinePost(Route)]
    /// <remarks>
    /// Returns <c>(Events, IResult)</c>, and getting there took three attempts — each failing differently.
    ///
    ///   (SubjectRevised?, ProblemDetails?)          a null event is still handed to Marten:
    ///                                               ArgumentNullException (Parameter 'eventData')
    ///   (Events, ProblemDetails) + [EmptyResponse]  compiles, runs, and SILENTLY IGNORES the refusal —
    ///                                               [EmptyResponse] forces 204 and the ProblemDetails never
    ///                                               reaches the wire. The worst of the three, because the
    ///                                               endpoint reports success for a rejected command.
    ///   (Events, IResult)                           the response is explicit and nothing overrides it.
    ///
    /// The lesson generalises past this endpoint: <c>[EmptyResponse]</c> is fine for a slice that cannot
    /// refuse, and actively dangerous for one that can.
    ///
    /// A nullable event does NOT mean "append nothing" — Wolverine hands whatever is in that slot to Marten,
    /// and a null arrives as <c>ArgumentNullException: Value cannot be null. (Parameter 'eventData')</c> from
    /// deep inside EventStream.AppendOne, which says nothing about the endpoint that caused it. An empty
    /// <c>Events</c> is how a decider says it decided against.
    ///
    /// <c>WolverineContinue.NoProblems</c> is the other half: ProblemDetails in a return tuple is a
    /// short-circuit, so the success path has to say explicitly that there is no problem.
    ///
    /// Both mistakes are the same shape — a return slot means "do this", and null is not a way of saying
    /// "skip it". The message handler next door hit the identical wall from the other direction.
    /// </remarks>
    public static (IResult, Events) Revise(
        ReviseSubject command,
        [WriteAggregate(nameof(ReviseSubject.EmailId), Required = false)] ReviseSubjectState? draft)
    {
        var events = new Events();

        // NotDrafted. A missing stream and a stream nobody drafted into fold to the same thing.
        if (draft is not { Drafted: true })
            return (Rejections.Problem("NotDrafted",
                $"No draft {command.EmailId} exists, so there is no subject to revise."), events);


        // NothingChanged — the rule that needs the FOLD. Nothing about the request reveals it.
        if (string.Equals(draft.Subject, command.Subject, StringComparison.Ordinal))
            return (Rejections.Problem("NothingChanged",
                "The subject submitted is the one the draft already has."), events);

        events += new SubjectRevised(command.EmailId, command.Subject, DateTimeOffset.UtcNow);
        return (Results.NoContent(), events);
    }
}

/// <summary>
/// The rule name goes in <c>Title</c>, which is what Wolverine.HTTP's FluentValidation middleware already does
/// for periphery failures. So a caller reads the rule name the same way whether it was refused at the
/// periphery or by the decider — one contract, two enforcement points.
/// </summary>
public static class Rejections
{
    public static IResult Problem(string rule, string detail) =>
        Results.Problem(title: rule, detail: detail, statusCode: 400);
}
